package tr.kasabatr.boya;
import java.util.*;
import org.bukkit.*;import org.bukkit.boss.*;import org.bukkit.entity.*;import org.bukkit.event.entity.ProjectileHitEvent;import org.bukkit.inventory.*;import org.bukkit.inventory.meta.LeatherArmorMeta;import org.bukkit.potion.*;
final class BoyaRoom {
 enum Phase{RUNNING,ENDING,CLOSED}
 record Shot(UUID owner,PaintTeam team,int tick){}
 final KasabaBoyaPlugin plugin;final int id;final PaintMap map;final boolean practice;final UUID result=UUID.randomUUID();
 final Set<UUID> players=new LinkedHashSet<>();final Map<UUID,PaintTeam> teams=new LinkedHashMap<>();final Map<UUID,Integer> lastShot=new HashMap<>();final Map<UUID,Shot> shots=new HashMap<>();final PaintGrid grid;
 final BossBar bar=Bukkit.createBossBar("§bBoya Savaşı",BarColor.WHITE,BarStyle.SOLID);
 World world;Phase phase=Phase.RUNNING;long startedAt,finishAt;int duration;
 BoyaRoom(KasabaBoyaPlugin plugin,int id,PaintMap map,boolean practice){this.plugin=plugin;this.id=id;this.map=map;this.practice=practice;grid=new PaintGrid(map.paintable);}
 boolean active(){return phase==Phase.RUNNING;}
 boolean contains(Location at){return at.getWorld()==world&&map.contains(at);}
 void start(){
  for(PaintMap.Tile tile:map.paintable)world.getBlockAt(tile.x(),tile.y(),tile.z()).setType(Material.WHITE_CONCRETE,false);
  List<UUID> order=new ArrayList<>(players);Collections.shuffle(order,plugin.random);for(int i=0;i<order.size();i++)teams.put(order.get(i),i%2==0?PaintTeam.RED:PaintTeam.BLUE);
  int red=0,blue=0;for(UUID id:order){Player p=Bukkit.getPlayer(id);if(p==null||!plugin.auth(p))throw new IllegalArgumentException("Oyuncu ayrıldı.");PaintTeam team=teams.get(id);plugin.prepare(p,map.spawn(world,team,team==PaintTeam.RED?red++:blue++));plugin.tools(p);ItemStack chest=new ItemStack(Material.LEATHER_CHESTPLATE);LeatherArmorMeta meta=(LeatherArmorMeta)chest.getItemMeta();meta.setColor(team.color);meta.setUnbreakable(true);meta.setDisplayName(team.label+" Takım");chest.setItemMeta(meta);p.getInventory().setChestplate(chest);p.getInventory().setHeldItemSlot(0);bar.addPlayer(p);p.sendTitle(team.label+" TAKIM","§fBoya tabancası: sağ tık • Daha fazla alan boya",5,65,10);}
  startedAt=System.currentTimeMillis();duration=Math.clamp(plugin.getConfig().getInt("match-seconds",180),60,600);update(duration);
 }
 void tick(long now){if(phase==Phase.CLOSED)return;if(phase==Phase.ENDING){bar.setTitle("§aSonuçlar §8• §eLobiye "+Math.max(0,(finishAt-now+999)/1000)+" sn");if(now>=finishAt)close();return;}
  for(UUID id:List.copyOf(players)){Player p=Bukkit.getPlayer(id);if(p==null||!p.isOnline()){plugin.abandon(id);plugin.leave(id);continue;}if(p.isDead()){plugin.toLobby(p);continue;}if(!contains(p.getLocation())){plugin.teleport(p,map.spawn(world,teams.get(id),1));}p.setFlying(false);p.setAllowFlight(false);p.setGravity(true);}
  for(var entry:List.copyOf(shots.entrySet())){Entity ball=Bukkit.getEntity(entry.getKey());if(ball==null||Bukkit.getCurrentTick()-entry.getValue().tick>120){shots.remove(entry.getKey());plugin.shotRooms.remove(entry.getKey());if(ball!=null)ball.remove();}}
  if(!active())return;int left=(int)Math.max(0,duration-(now-startedAt)/1000);update(left);if(left==0)finish(grid.winner(),"Süre doldu.");
 }
 void update(int remaining){int red=grid.count(PaintTeam.RED),blue=grid.count(PaintTeam.BLUE);bar.setTitle((practice?"§eDENEME §8• ":"")+"§cKırmızı %"+Math.round(red*100.0/map.paintable.size())+" §8/ §9Mavi %"+Math.round(blue*100.0/map.paintable.size())+" §8• §f"+(remaining/60)+":"+String.format("%02d",remaining%60));bar.setColor(red==blue?BarColor.WHITE:red>blue?BarColor.RED:BarColor.BLUE);bar.setProgress(Math.clamp(remaining/(double)duration,0,1));}
 void shoot(Player p){UUID id=p.getUniqueId();if(!active()||!players.contains(id)||p.getWorld()!=world)return;int tick=Bukkit.getCurrentTick(),cooldown=Math.clamp(plugin.getConfig().getInt("shot-cooldown-ticks",6),3,20);if(tick-lastShot.getOrDefault(id,Integer.MIN_VALUE/2)<cooldown)return;lastShot.put(id,tick);Snowball ball=p.launchProjectile(Snowball.class);ball.setVelocity(ball.getVelocity().multiply(1.25));shots.put(ball.getUniqueId(),new Shot(id,teams.get(id),tick));plugin.shotRooms.put(ball.getUniqueId(),this);p.playSound(p.getLocation(),Sound.ENTITY_SNOWBALL_THROW,.45f,1.1f);}
 void hit(ProjectileHitEvent event){Shot shot=shots.remove(event.getEntity().getUniqueId());if(shot==null||!active()||!players.contains(shot.owner)||event.getEntity().getWorld()!=world)return;
  PaintMap.Tile centre=null;if(event.getHitEntity() instanceof Player victim){if(!players.contains(victim.getUniqueId())||victim.getWorld()!=world||teams.get(victim.getUniqueId())==shot.team)return;victim.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS,30,1,false,false));Location feet=victim.getLocation();for(int y=Math.min(83,feet.getBlockY()-1);y>=79;y--){var candidate=new PaintMap.Tile(feet.getBlockX(),y,feet.getBlockZ());if(map.paintable.contains(candidate)){centre=candidate;break;}}}
  else if(event.getHitBlock()!=null){var b=event.getHitBlock();centre=new PaintMap.Tile(b.getX(),b.getY(),b.getZ());}
  if(centre!=null&&map.paintable.contains(centre))splash(centre,shot.team);
 }
 void splash(PaintMap.Tile centre,PaintTeam team){if(!active())return;int radius=Math.clamp(plugin.getConfig().getInt("shot-splash-radius",2),1,3);for(PaintMap.Tile tile:grid.splash(centre,team,radius))world.getBlockAt(tile.x(),tile.y(),tile.z()).setType(team.block,false);world.spawnParticle(Particle.DUST,new Location(world,centre.x()+.5,centre.y()+1.1,centre.z()+.5),12,.75,.45,.75,new Particle.DustOptions(team.color,1.2f));update((int)Math.max(0,duration-(System.currentTimeMillis()-startedAt)/1000));}
 void remove(UUID id){players.remove(id);teams.remove(id);lastShot.remove(id);Player p=Bukkit.getPlayer(id);if(p!=null)bar.removePlayer(p);for(var entry:List.copyOf(shots.entrySet()))if(entry.getValue().owner.equals(id)){Entity ball=Bukkit.getEntity(entry.getKey());if(ball!=null)ball.remove();plugin.shotRooms.remove(entry.getKey());shots.remove(entry.getKey());}if(plugin.stopping||!active()){if(players.isEmpty())close();return;}if(players.isEmpty())close();else if(!teams.containsValue(PaintTeam.RED))finish(PaintTeam.BLUE,"Kırmızı takım ayrıldı.");else if(!teams.containsValue(PaintTeam.BLUE))finish(PaintTeam.RED,"Mavi takım ayrıldı.");}
 void finish(PaintTeam winner,String reason){if(!active())return;phase=Phase.ENDING;finishAt=System.currentTimeMillis()+5000;clearShots();if(winner!=null&&!practice&&!plugin.stopping)plugin.hub.recordGameResult(plugin,KasabaBoyaPlugin.ID,result,players.stream().filter(id->teams.get(id)==winner).toList());String text=winner==null?"§eBERABERE":winner.label+" KAZANDI";for(UUID id:players){Player p=Bukkit.getPlayer(id);if(p!=null){p.sendTitle(text,"§f5 saniye sonra Boya Savaşı lobisi",5,70,10);plugin.tell(p,reason+" §c"+grid.count(PaintTeam.RED)+" §8/ §9"+grid.count(PaintTeam.BLUE)+" §7boyalı blok.");}}bar.setColor(BarColor.GREEN);bar.setProgress(1);}
 void clearShots(){for(UUID id:List.copyOf(shots.keySet())){Entity ball=Bukkit.getEntity(id);if(ball!=null)ball.remove();plugin.shotRooms.remove(id);}shots.clear();}
 void close(){if(phase==Phase.CLOSED)return;phase=Phase.CLOSED;bar.removeAll();clearShots();plugin.rooms.remove(id,this);for(UUID id:List.copyOf(players)){plugin.membership.remove(id,this);Player p=Bukkit.getPlayer(id);if(p!=null&&plugin.visitors.contains(id)&&!plugin.stopping)plugin.returnGameLobby(p,0);}players.clear();teams.clear();if(world!=null)plugin.closeWhenEmpty(world,0);}
}
